from pathlib import Path
import json,collections,hashlib
root=Path.cwd(); results=root/'Codex Work/Sub-Agents/Results'; ui=root/'Codex Work/Deep-Audit/UI-UX';ui.mkdir(parents=True,exist_ok=True)
ledger=json.loads((results/'ui-ledger.json').read_text(encoding='utf-8-sig'))
indexpath=root/'Codex Work/Deep-Audit/Source-Inventory/Current/FUNCTION_INDEX.json'
idx=json.loads(indexpath.read_text(encoding='utf-8-sig'))
byfile={e['path']:e for e in ledger['files']}; functions=[]
for d in idx['declarations']:
 if not d.get('isCallable') or d['path'] not in byfile:continue
 f=byfile[d['path']]; name=d['name'].split('(')[0].split('<')[0]
 # Exact manually authored review heading only; a function merely mentioned by another
 # paragraph is NOT automatically promoted. Accessors/lambdas stay unknown unless headed.
 reviewed=bool(f.get('fileReviewed')) and name in f.get('functionReviewAnchors',[])
 functions.append({k:d[k] for k in ['id','path','kind','name','qualifiedSymbol','startLine','endLine','semanticStatus']} | {'functionReviewed':reviewed,'reviewStatus':'MANUALLY_REVIEWED_WITH_REPORTED_REASONING' if reviewed else 'NOT_ANALYZED','reviewEvidence':f.get('report') if reviewed else None})
counts=collections.Counter(f['reviewStatus'] for f in functions)
payload={'baseline':ledger['baseline'],'inventory':str(indexpath.relative_to(root)).replace('\\','/'),'inventorySHA256':hashlib.sha256(indexpath.read_bytes()).hexdigest(),'mappingPolicy':'Conservative exact manually authored function/resource heading to Roslyn callable name. File review NEVER implies every function reviewed. Unmatched lambdas/accessors/overloads remain NOT_ANALYZED. Mapping is not semantic analysis; semantic spans supplied by parent Roslyn.','counts':dict(counts),'functions':functions}
(results/'ui-function-review-ledger.json').write_text(json.dumps(payload,ensure_ascii=False,indent=2),encoding='utf-8')
missing=[e['path'] for e in ledger['files'] if e['status']=='NOT_ANALYZED'];partial=[e['path'] for e in ledger['files'] if e['status']=='PARTIALLY_REVIEWED']
findings=json.loads((results/'ui-findings.json').read_text(encoding='utf-8-sig'))
text=['# UI/client audit checkpoint',f'Baseline: `{ledger["baseline"]}`.',f'Scope: **{len(ledger["files"])} tracked files**. File counts: `{json.dumps(ledger["counts"])}`. These source-review labels do not assert exhaustive function review or native runtime verification.',f'Conservative Roslyn callable review map: `{json.dumps(dict(counts))}`. See `Sub-Agents/Results/ui-function-review-ledger.json` for exact source spans and remaining functions.','## Highest-priority findings','- Primary cashier and treasury financial retry identity survives only process memory (UI-001).','- Persisted electronic confirmation/cancellation cannot reconstruct visible checkout context and blocks ordinary recovery (UI-005).','- Pickup kitchen-before-payment stage is not represented in active client (UI-003; backend corroboration separate).','- CallCenter old customer lookup may overwrite latest phone/order identity (UI-007).','- Customer-copy reprint includes kitchen by DTO default in CallCenter (UI-012, printing peer cross-check).','- Restore completion UI expects Completed while actual handler returns Succeeded (UI-014).','- Expense unselected category and payment choices hardcode white surface with pale dark text (UI-002).','## Expense visual root and limitations','The expense category values/bindings were traced to CashierView.xaml:313–340, StringEqualsToBrushConverter, ThemeResources.Get, Colors.xaml, SecondaryButtonStyle and root RequestedTheme. The category model is not the root of pale text: view-instance background overrides use literal WhiteBrush, while unselected text uses themed TextPrimaryBrush. Dark source token #E6E9EE on white has very low computed contrast. Selected state uses accent/white. Checkout payment buttons repeat this pattern.','No screenshot was supplied to this reviewer, no desktop interaction performed, and no pixel rendering/contrast measurements claimed. ActualTheme/system override and live converter refresh remain runtime verification gaps. Do not globally change WhiteBrush because paper and on-accent uses rely on literal white. Stored expense category keys must remain unchanged.','## Runtime and safety','No application UI, database, business data, printer, source/configuration or package changes were made by this reviewer. No tests/builds/application commands were executed. Test source review distinguishes fake HTTP/stub timers/headless linked VM from actual backend/WinUI runtime. User active drafts preserved.','## Per-file report navigation','Authoritative reports: `Deep-Audit/File-Reports/<tracked path>.md`; ledger: `Sub-Agents/Results/ui-ledger.json`; findings/candidates: `Sub-Agents/Results/ui-findings.json`. Function map reports reviewed and NOT_ANALYZED separately. No clean/production-ready claim.','## Remaining partially reviewed files']
text += [f'- `{p}`' for p in partial] or ['ZERO']
text += ['## Remaining unreviewed files']+[f'- `{p}`' for p in missing]
(ui/'ui-summary.md').write_text('\n\n'.join(text)+'\n',encoding='utf-8')
print(json.dumps({'fileCounts':ledger['counts'],'functionCounts':dict(counts),'findings':len(findings['findings']),'summary':str(ui/'ui-summary.md')},ensure_ascii=False))
